INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000010010','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000010010","revision":1,"targetId":"80000000-0000-4000-8000-000000000101","prompt":"Im Sachbuch ist neben dem Text eine beschriftete Zeichnung der menschlichen Lunge zu sehen. Diese bildliche Darstellung nennt man eine ___.","instruction":{"en":"Select the noun that best completes the sentence.","de":"Wähle das Nomen, das den Satz am besten ergänzt."},"hint":{"en":"A visual figure can show a technical relationship better than prose.","de":"Eine grafische Darstellung erklärt einen Zusammenhang oft anschaulicher als Text."},"options":[{"id":"0","text":"Bildunterschrift"},{"id":"1","text":"Textpassage"},{"id":"2","text":"Überschrift"},{"id":"3","text":"Abbildung"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"3"}],"explanation":{"en":"Abbildung denotes a figure or illustration reproduced in a document.","de":"Eine Abbildung ist eine bildliche Darstellung in einem Dokument."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Im Sachbuch ist neben dem Text eine beschriftete Zeichnung der menschlichen Lunge zu sehen. Diese bildliche Darstellung nennt man eine Abbildung.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 wording, 2026-10-28; lemma and lexical facts from pinned GM2 source apps/web/data/pos/nouns.jsonl:L2 (f6cee93b78bda41fcdb1c744e4cf7450cfe22329da93265169e84ce84e778b52). Legacy flags and examples are unverified; no source examples copied. No external dataset or publication rights certification. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T11:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; incremental release subject to technical gates. See enrichment-reviewed-release.md.','approved');
