INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000010021','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000010021","revision":1,"targetId":"80000000-0000-4000-8000-000000000102","prompt":"Die Kinder freuten sich auf die erste Nacht im Zelt. Sie wollten etwas Neues erleben und empfanden die Übernachtung als spannendes ___.","instruction":{"en":"Select the noun that best completes the sentence.","de":"Wähle das Nomen, das den Satz am besten ergänzt."},"hint":{"en":"Think of a memorable experience beyond an ordinary routine.","de":"Denke an ein ungewöhnliches Erlebnis außerhalb des Alltags."},"slots":[{"id":"noun","label":"Nomen","options":[{"id":"0","text":"Rätsel"},{"id":"1","text":"Unglück"},{"id":"2","text":"Versehen"},{"id":"3","text":"Abenteuer"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"noun","optionId":"3"}]}],"explanation":{"en":"An Abenteuer is an unusual or exciting experience, not a routine activity.","de":"Ein Abenteuer ist ein ungewöhnliches, oft aufregendes Erlebnis."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Kinder freuten sich auf die erste Nacht im Zelt. Sie wollten etwas Neues erleben und empfanden die Übernachtung als spannendes Abenteuer.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 wording, 2026-10-28; lemma and lexical facts from pinned GM2 source apps/web/data/pos/nouns.jsonl:L4 (af3135572aca5c3b347ef497f4c841f34a1774c172a1c9ca4546e8235ffe6297). Legacy flags and examples are unverified; no source examples copied. No external dataset or publication rights certification. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T11:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; incremental re