INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000010041','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000010041","revision":1,"targetId":"80000000-0000-4000-8000-000000000104","prompt":"Der volle ___ mit den Küchenabfällen muss vor dem Urlaub geleert werden.","instruction":{"en":"Select the noun that best completes the sentence.","de":"Wähle das Nomen, das den Satz am besten ergänzt."},"hint":{"en":"A container for paper scraps or kitchen waste is needed.","de":"Gesucht ist ein Behälter für Papierschnipsel oder Küchenabfälle."},"slots":[{"id":"noun","label":"Nomen","options":[{"id":"0","text":"Vorratsbehälter"},{"id":"1","text":"Abfalleimer"},{"id":"2","text":"Wasserkocher"},{"id":"3","text":"Geschirrkorb"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"noun","optionId":"1"}]}],"explanation":{"en":"Abfalleimer names a small rubbish bin; its plural is also Abfalleimer.","de":"Ein Abfalleimer ist ein Behälter für Müll; der Plural lautet ebenfalls Abfalleimer."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Der volle Abfalleimer mit den Küchenabfällen muss vor dem Urlaub geleert werden.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 wording, 2026-10-28; lemma and lexical facts from pinned GM2 source apps/web/data/pos/nouns.jsonl:L7 (e863b84d99046a55a8f6b18034cb4bc50c148e65ae9a412fbe39773146f38545). Legacy flags and examples are unverified; no source examples copied. No external dataset or publication rights certification. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T11:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; incremental release subject to technical gates. See enrichment-reviewed-release.md.','approved');
