INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000010051','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000010051","revision":1,"targetId":"80000000-0000-4000-8000-000000000105","prompt":"Mehrwegbecher sollen verhindern, dass Einwegmüll entsteht. Die Stadt fördert damit die ___.","instruction":{"en":"Select the noun that best completes the sentence.","de":"Wähle das Nomen, das den Satz am besten ergänzt."},"hint":{"en":"The goal is not to process waste but to prevent it from arising.","de":"Hier geht es darum, Müll gar nicht erst entstehen zu lassen."},"slots":[{"id":"noun","label":"Nomen","options":[{"id":"0","text":"Abfallvermeidung"},{"id":"1","text":"Abfallverwertung"},{"id":"2","text":"Müllentsorgung"},{"id":"3","text":"Wertstofftrennung"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"noun","optionId":"0"}]}],"explanation":{"en":"Abfallvermeidung prevents materials from becoming waste in the first place.","de":"Abfallvermeidung setzt an, bevor Müll entsteht; Entsorgung oder Recycling erfolgen erst danach."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Mehrwegbecher sollen verhindern, dass Einwegmüll entsteht. Die Stadt fördert damit die Abfallvermeidung.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 wording, 2026-10-28; lemma and lexical facts from pinned GM2 source apps/web/data/pos/nouns.jsonl:L8 (f611dfb913456f7161dce3d561b3c059ee3f2e0c02f0e780abcc1353fe93524f). Legacy flags and examples are unverified; no source examples copied. No external dataset or publication rights certification. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T11:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; incremental release subject to technical gates. See enrichment-reviewed-release.md.','approved');
