INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000010091','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000010091","revision":1,"targetId":"80000000-0000-4000-8000-000000000109","prompt":"Als wiederholt Wasser in den Keller drang, musste die Hausverwaltung rasch ___ schaffen.","instruction":{"en":"Select the noun that best completes the sentence.","de":"Wähle das Nomen, das den Satz am besten ergänzt."},"hint":{"en":"The established expression with schaffen means to put a problem right.","de":"Gesucht ist die feste Verbindung mit schaffen, wenn ein Missstand beseitigt werden soll."},"slots":[{"id":"noun","label":"Nomen","options":[{"id":"0","text":"Abhilfe"},{"id":"1","text":"Auskunft"},{"id":"2","text":"Ordnung"},{"id":"3","text":"Übersicht"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"noun","optionId":"0"}]}],"explanation":{"en":"Abhilfe schaffen means to remedy a problem or improve an unsatisfactory situation.","de":"Abhilfe schaffen bedeutet, einen Missstand zu beseitigen oder die Lage zu verbessern."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Als wiederholt Wasser in den Keller drang, musste die Hausverwaltung rasch Abhilfe schaffen.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 wording, 2026-10-28; lemma and lexical facts from pinned GM2 source apps/web/data/pos/nouns.jsonl:L13 (0e602048cea82d01a80d21d9dfdf26e311666e3bb6b8b7b5884edb1e25376366). Legacy flags and examples are unverified; no source examples copied. No external dataset or publication rights certification. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T11:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; incremental release subject to technic