INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000010100','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000010100","revision":1,"targetId":"80000000-0000-4000-8000-000000000110","prompt":"Mira hatte gerade die gymnasiale Oberstufe mit der allgemeinen Hochschulreife abgeschlossen. Nach dem ___ bewarb sie sich erstmals an verschiedenen Universitäten.","instruction":{"en":"Select the noun that best completes the sentence.","de":"Wähle das Nomen, das den Satz am besten ergänzt."},"hint":{"en":"Think of the qualification commonly used to apply to university after school in Germany.","de":"Denke an den Schulabschluss, mit dem man in Deutschland üblicherweise ein Studium beginnen kann."},"options":[{"id":"0","text":"Praktikum"},{"id":"1","text":"Studium"},{"id":"2","text":"Abitur"},{"id":"3","text":"Vorstellungsgespräch"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"Abitur is a German school-leaving qualification providing general university entrance eligibility. The plural Abiture is valid but uncommon.","de":"Das Abitur ist ein Schulabschluss, der die allgemeine Hochschulreife vermittelt. Der Plural Abiture ist möglich, aber selten."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Mira hatte gerade die gymnasiale Oberstufe mit der allgemeinen Hochschulreife abgeschlossen. Nach dem Abitur bewarb sie sich erstmals an verschiedenen Universitäten.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 wording, 2026-10-28; lemma and lexical facts from pinned GM2 source apps/web/data/pos/nouns.jsonl:L14 (09f965a8d126dfad97745811d5312c276257856aa2fb7b4c3b5c33fd9485a4e3). Legacy flags and examples are unverified; no source examples copied. No external dataset or publication rights certification. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T11:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; incremental release subject to technical gates. See enrichment-reviewed-release.md.','approved');
