INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000010101','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000010101","revision":1,"targetId":"80000000-0000-4000-8000-000000000110","prompt":"Sie besucht die letzte Klasse der gymnasialen Oberstufe und bereitet sich auf das ___ als Schulabschluss vor, weil sie später Medizin studieren möchte.","instruction":{"en":"Select the noun that best completes the sentence.","de":"Wähle das Nomen, das den Satz am besten ergänzt."},"hint":{"en":"Think of the qualification commonly used to apply to university after school in Germany.","de":"Denke an den Schulabschluss, mit dem man in Deutschland üblicherweise ein Studium beginnen kann."},"slots":[{"id":"noun","label":"Nomen","options":[{"id":"0","text":"Praktikum"},{"id":"1","text":"Studium"},{"id":"2","text":"Bewerbungsgespräch"},{"id":"3","text":"Abitur"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"noun","optionId":"3"}]}],"explanation":{"en":"Abitur is a German school-leaving qualification providing general university entrance eligibility. The plural Abiture is valid but uncommon.","de":"Das Abitur ist ein Schulabschluss, der die allgemeine Hochschulreife vermittelt. Der Plural Abiture ist möglich, aber selten."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Sie besucht die letzte Klasse der gymnasialen Oberstufe und bereitet sich auf das Abitur als Schulabschluss vor, weil sie später Medizin studieren möchte.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 wording, 2026-10-28; lemma and lexical facts from pinned GM2 source apps/web/data/pos/nouns.jsonl:L14 (09f965a8d126dfad97745811d5312c276257856aa2fb7b4c3b5c33fd9485a4e3). Legacy flags and examples are unverified; no source examples copied. No external dataset or publication rights certificati